window.kbPageData["views/entry/k-4f6259035ff4c910"] = {"key":"entry/k-4f6259035ff4c910","state":{"route":"entry/k-4f6259035ff4c910"},"node":{"id":"k-4f6259035ff4c910","mode":"k","title":"体验与感受","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["“体验”与“感受”的词义区别"],"qs":["江苏 2023 A类 行测#34"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"体验侧重亲身经历，也可指由经历形成的体会。感受侧重受到外界影响后产生的主观感觉或体会。","review":{"definition":"体验侧重亲身经历，也可指由经历形成的体会。感受侧重受到外界影响后产生的主观感觉或体会。","explanation":"第34题中的“这些用心之处”指细致的服务和别出心裁的产品设计。“情绪体验”把良好的情绪与消费者接受服务、使用产品的过程联系起来。“情绪感受”也能指消费者产生的感觉，但对亲身经历这一层着墨较少，因此本题选“体验”。","references":[],"evidence":"“体验”指在实践中认识事物、亲身经历","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#34":{"paper":"江苏 2023 A类 行测","n":34,"mod":"言语理解与表达","src":["22304fe4c340e19d7902.pdf",7],"asrc":["be17f9afe070cf13a0fb.pdf",11],"card":"e6ee20d5056925dda6dacc63","links":[{"id":"k-4f6259035ff4c910","role":"解题依据","why":"“体验”突出亲身经历，“感受”侧重受到影响或形成感受，区别关系到次空与产品和服务的对应。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4f6259035ff4c910":[["江苏 2023 A类 行测#34"]]}};
